  (990173,'Esentai Mall','Премиальный торговый центр Алматы с международными люксовыми брендами, ресторанами и сервисами; расположен на проспекте Аль-Фараби.','mall',43.2186,76.92793,'https://assets.harpersbazaar.kz/uploads/harpersbazaar/2019/04/esentai-mall.jpg',null,false,'Казахстан','Алматы','проспект Аль-Фараби, 77/8, Алматы, Казахстан',null,null,null,null,null,null,'https://www.openstreetmap.org/?mlat=43.2186&mlon=76.92793#map=17/43.2186/76.92793',array['https://esentai.com/contacts','https://mapcarta.com/W1458250211','https://harpersbazaar.kz/esentai-mall-new-strategy','https://assets.harpersbazaar.kz/uploads/harpersbazaar/2019/04/esentai-mall.jpg']::text[]),
  (63,'Старый город (Ичери-Шехер)','Исторический центр Баку за крепостными стенами: узкие улицы, мечети, караван-сараи. Входит в список Всемирного наследия ЮНЕСКО.','attraction',40.366,49.837,'https://worldheritagesites.net/wp-content/uploads/2025/06/Walled_City_Baku_2.jpg',null,true,'Азербайджан','Баку','Icherisheher (Old City), Baku, Azerbaijan',null,null,null,null,null,null,'https://www.google.com/maps/search/?api=1&query=40.366,49.837',array['https://worldheritagesites.net/walled-city-of-baku/','https://worldheritagesites.net/wp-content/uploads/2025/06/Walled_City_Baku_2.jpg','https://www.icherisheher.gov.az/en/activity/historical-reference']::text[]),
