  (65,'Башни Пламени (Flame Towers)','Три небоскрёба в форме языков пламени с вечерней подсветкой. Хорошо видны с набережной и из многих точек города.','attraction',40.35998,49.82625,'https://spectra.mhi.com/sites/g/files/jwhtju2216/files/styles/crop_freeform/public/Baku%2C-Azerbaijan-at-night.jpeg?itok=LK1awdF4',null,false,'Азербайджан','Баку','Mehdi Huseyn Street 1A, Baku, Azerbaijan',null,null,null,null,null,null,'https://www.google.com/maps/search/?api=1&query=40.35998,49.82625',array['https://spectra.mhi.com/energy-transition/cop29-3-areas-of-focus-for-the-finance-cop','https://spectra.mhi.com/sites/g/files/jwhtju2216/files/styles/crop_freeform/public/Baku%2C-Azerbaijan-at-night.jpeg?itok=LK1awdF4','https://www.fairmont.com/en/hotels/baku/fairmont-baku-flame-towers/wellness/spa.html','https://mapcarta.com/W340060268']::text[]),
  (66,'Приморский бульвар','Набережная вдоль Каспийского моря: променад, парки, виды на залив.','embankment',40.368,49.8455,'https://hblimg.mmtcdn.com/content/hubble/img/additionalttdimages/mmt/activities/m_Baku_Boulevard_1_l_667_1000.jpg',null,true,'Азербайджан','Баку',null,null,null,null,null,null,null,'https://www.google.com/maps/search/?api=1&query=40.368,49.8455',array['https://www.makemytrip.com/tripideas/attractions/baku-boulevard','https://hblimg.mmtcdn.com/content/hubble/img/additionalttdimages/mmt/activities/m_Baku_Boulevard_1_l_667_1000.jpg']::text[]),
  (67,'Маленькая Венеция','Каналы и лодки на Приморском бульваре.','attraction',40.359,49.84,'https://www.advantour.com/img/azarbaijan/baku/little-venice-baku.jpg',null,true,'Азербайджан','Баку','Baku Boulevard, beside the Azerbaijan National Carpet Museum, Baku, Azerbaijan',null,null,null,null,null,null,'https://www.google.com/maps/search/?api=1&query=40.359,49.84',array['https://www.advantour.com/azerbaijan/baku/things-to-do.htm','https://www.advantour.com/img/azarbaijan/baku/little-venice-baku.jpg','https://inn.az/en/blog/little-venice-baku-location-boat-ride-prices-visitor-guide']::text[]),
